using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ──────────────────────────────────────────────
    //  CalculateTotal – DataRow tests
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0,  50.00,  DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero price yields zero")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity yields zero")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "100% tax doubles the price")]
    public void CalculateTotal_ReturnsExpectedAmount(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal – invalid input tests
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price")]
    public void CalculateTotal_NegativePrice_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    public void CalculateTotal_NegativeQuantity_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below 0")]
    [DataRow(10.00, 1, 1.01,  DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidTaxRate_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ──────────────────────────────────────────────
    //  ApplyDiscount – DataRow tests
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0,   100.00, DisplayName = "0% discount")]
    [DataRow(100.00, 10.0,  90.00,  DisplayName = "10% discount")]
    [DataRow(100.00, 50.0,  50.00,  DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00,   DisplayName = "100% discount (free)")]
    [DataRow(49.99,  20.0,  39.992, DisplayName = "Fractional result")]
    public void ApplyDiscount_ReturnsExpectedAmount(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, -1.0,  DisplayName = "Negative discount")]
    [DataRow(100.00, 100.1, DisplayName = "Discount above 100%")]
    public void ApplyDiscount_InvalidDiscount_Throws(
        double price, double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal – DynamicData tests
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> BulkOrderCases
    {
        get
        {
            // (unitPrice, quantity, taxRate, expected)
            yield return [9.99m,  100, 0.07m, 1068.93m];
            yield return [1.00m, 1000, 0.0m,  1000.00m];
            yield return [0.01m,  500, 0.05m, 5.25m];
        }
    }

    [TestMethod]
    [DynamicData(nameof(BulkOrderCases))]
    public void CalculateTotal_BulkOrders_ReturnsExpectedAmount(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }

    // ──────────────────────────────────────────────
    //  ApplyDiscount – DynamicData via method
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> GetChainedDiscountCases()
    {
        // Apply two successive discounts and verify the final price.
        // (originalPrice, firstDiscount, secondDiscount, expectedFinal)
        yield return [200.00m, 10.0m, 5.0m,  171.00m];
        yield return [500.00m, 25.0m, 10.0m, 337.50m];
        yield return [100.00m, 0.0m,  0.0m,  100.00m];
    }

    [TestMethod]
    [DynamicData(nameof(GetChainedDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_ChainedDiscounts_ReturnsExpectedAmount(
        decimal originalPrice, decimal firstDiscount, decimal secondDiscount, decimal expectedFinal)
    {
        var afterFirst = _calculator.ApplyDiscount(originalPrice, firstDiscount);
        var afterSecond = _calculator.ApplyDiscount(afterFirst, secondDiscount);

        Assert.AreEqual(expectedFinal, afterSecond);
    }
}

